package com.cvns.controller;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import com.cvns.dtos.RequestDtos.VaccineRequest;import com.cvns.dtos.ResponseDtos.ApiResponse;import com.cvns.service.VaccineService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;
@RestController @RequestMapping("/vaccines") @RequiredArgsConstructor public class VaccineController{private final VaccineService s;@GetMapping public ResponseEntity<?> list(){return ResponseEntity.ok(ApiResponse.success("Vaccines",s.list()));}@PostMapping @PreAuthorize("hasRole('ADMIN')")public ResponseEntity<?> add(@RequestBody @Valid VaccineRequest r){return ResponseEntity.status(201).body(ApiResponse.success("Vaccine added",s.add(r)));}@PutMapping("/{id}")@PreAuthorize("hasRole('ADMIN')")public ResponseEntity<?> update(@PathVariable Long id,@RequestBody @Valid VaccineRequest r){return ResponseEntity.ok(ApiResponse.success("Vaccine updated",s.update(id,r)));}@DeleteMapping("/{id}")@PreAuthorize("hasRole('ADMIN')")public ResponseEntity<?> delete(@PathVariable Long id){s.delete(id);return ResponseEntity.ok(ApiResponse.success("Vaccine deleted",null));}}
